function newId(){if(crypto.randomUUID)return crypto.randomUUID();const a=crypto.getRandomValues(new Uint8Array(16));a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;const h=[...a].map(n=>n.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
const PLUS_SB='https://aqmhjpcsasshttmkdkks.supabase.co',PLUS_PK='sb_publishable_J1dfCQXOgwJ46tp2Eo4GfQ_o74caYuQ';
let PE=[],PP=new Set(),pState=BukiCore.derive([]),syncStatus='local',syncTimer,scope='guest',syncBusy=false,syncEpoch=0,activeActivity='practice',plusView='hub',pageCleanup=null;
function localJSON(k,fallback){try{return JSON.parse(localStorage.getItem(k)||'null')??fallback}catch(e){return fallback}}
function sessionUser(){try{const t=localJSON('bukiSess',null)?.a;return t?JSON.parse(atob(t.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).sub||'guest':'guest'}catch(e){return 'guest'}}
function plusKey(){return 'bukiPlus:v2:'+scope}
function rebuild(){pState=BukiCore.derive(PE);S.known=[...pState.known];S.best=Math.max(pState.best,0);S.wc=pState.writingCount+pState.essaysList.length;S.wb=pState.writingBest;S.gw=Object.keys(pState.review).filter(id=>id.startsWith('grammar:')&&pState.review[id].streak===0).map(id=>id.slice(8))}
function persistPlus(){try{localStorage.setItem(plusKey(),JSON.stringify({events:PE,pending:[...PP]}));return true}catch(e){syncStatus='storage';updateSyncLabel();return false}}
function eventRecord(kind,payload){const e={id:newId(),at:Math.max(Date.now(),(PE.at(-1)?.at||0)+1),kind,payload};PE=BukiCore.merge(PE,[e]);PP.add(e.id);rebuild();persistPlus();queueSync();return e}
function enterScope(){syncEpoch++;scope=sessionUser();const cache=localJSON(plusKey(),{});PE=BukiCore.merge(cache.events||[]);PP=new Set(cache.pending||[]);syncStatus=scope==='guest'?'local':'pending';rebuild();if(scope!=='guest')syncPlus();hub()}
async function plusToken(){let s=localJSON('bukiSess',null);if(!s)return null;if(Date.now()<s.e)return s.a;const r=await fetch(PLUS_SB+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:PLUS_PK,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.r})});if(!r.ok)throw Error('auth');const j=await r.json();if(!j.access_token)throw Error('auth');s={a:j.access_token,r:j.refresh_token,e:Date.now()+(j.expires_in||3600)*1000-60000};localStorage.setItem('bukiSess',JSON.stringify(s));return s.a}
async function plusAPI(path,method='GET',body,token){const t=token||await plusToken();if(!t)throw Error('auth');const r=await fetch(PLUS_SB+'/rest/v1/'+path,{method,headers:{apikey:PLUS_PK,Authorization:'Bearer '+t,'Content-Type':'application/json',Prefer:'resolution=ignore-duplicates,return=minimal'},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok){let j={};try{j=await r.json()}catch(e){}throw Error(r.status===401?'auth':r.status===404||j.code==='42P01'||j.code==='PGRST205'?'setup':'network')}if(r.status===204||r.headers.get('content-length')==='0')return null;const text=await r.text();return text?JSON.parse(text):null}
function queueSync(){clearTimeout(syncTimer);if(scope!=='guest')syncTimer=setTimeout(syncPlus,1500)}
function syncMessage(){return ({synced:L('Hesabınla eşitlendi','Synced to your account'),pending:L('Eşitleniyor…','Syncing…'),offline:L('Çevrimdışı; bu cihazda saklandı','Offline; saved on this device'),setup:L('Bulut ilerleme kaydı için ek kurulum bekleniyor','Cloud progress setup is pending'),auth:L('Eşitlemek için tekrar giriş yap','Sign in again to sync'),storage:L('Bu cihazda kayıt alanı dolu; yedek indir','Device storage is full; download a backup'),local:L('Bu cihazda saklanıyor','Saved on this device')})[syncStatus]||L('Eşitleme tekrar denenecek','Sync will be retried')}
function updateSyncLabel(){document.querySelectorAll('[data-sync]').forEach(el=>el.textContent=syncMessage())}
async function syncPlus(){if(scope==='guest')return;if(syncBusy){queueSync();return}syncBusy=true;const generation=syncEpoch,user=scope;syncStatus='pending';updateSyncLabel();try{const token=await plusToken();if(generation!==syncEpoch)return;
const pending=PE.filter(e=>PP.has(e.id));for(let i=0;i<pending.length;i+=100){const batch=pending.slice(i,i+100);await plusAPI('buki_learning_events?on_conflict=user_id,id','POST',batch.map(e=>({user_id:user,id:e.id,client_at:new Date(e.at).toISOString(),kind:e.kind,payload:e.payload})),token);if(generation!==syncEpoch)return;batch.forEach(e=>PP.delete(e.id));persistPlus()}
let cursor=0,received=[];while(true){const rows=await plusAPI('buki_learning_events?select=id,seq,client_at,kind,payload&user_id=eq.'+encodeURIComponent(user)+'&seq=gt.'+cursor+'&order=seq.asc&limit=500','GET',null,token);if(generation!==syncEpoch)return;if(!Array.isArray(rows))throw Error('network');for(const r of rows)received.push({id:r.id,at:Date.parse(r.client_at),kind:r.kind,payload:r.payload});if(rows.length<500)break;cursor=rows[rows.length-1].seq}
PE=BukiCore.merge(PE,received);rebuild();syncStatus='synced';persistPlus();if(PP.size)queueSync();
}catch(e){if(generation!==syncEpoch)return;syncStatus=['setup','auth'].includes(e.message)?e.message:navigator.onLine?'network':'offline'}finally{syncBusy=false;updateSyncLabel()}}
function plusRender(html,view){if(pageCleanup){pageCleanup();pageCleanup=null}plusView=view||'other';$(html)}
function backBar(title){return `<div class=bar><button onclick="hub()">← ${L('Ana sayfa','Home')}</button><span>${title}</span></div>`}
function topicName(id){if(id.startsWith('grammar:'))return G[+id.split(':')[1]]?.n||'Grammar';return ({vocab:L('Kelime','Vocabulary'),collocation:'Collocations',reading:'Reading',listening:L('Dinleme','Listening')})[id]||id}
function allQuestions(){return [...W.map(qf),...G.flatMap((_,i)=>gq(i)),...COL.map(collQuestion)]}
function itemId(q){return q.w.coll?q.w.id:q.w.id?'grammar:'+q.w.id:'vocab:'+q.w.w}
function recordAnswer(q,ok,hint){if(!q?.w)return;eventRecord('answer',{item:itemId(q),topic:q.w.coll?'collocation':q.w.id?'grammar:'+q.w.id.split(':')[0]:'vocab',ok:!!ok,hint:!!hint,mode:activeActivity,...(W.includes(q.w)?{word:ok?q.w.w:null}:{})})}
