reviewHome=function(){const due=reviewPool();plusRender(backBar('Collocations')+`<div class=card><h1>${L('Collocation atölyesi','Collocation workshop')}</h1><p>${L('Kelimeleri tek başına değil, doğal birliktelikleriyle öğren.','Learn words as natural partnerships.')}</p><small>${pState.due.length} ${L('tekrar zamanı geldi','items due for review')}</small></div><div class=grid><button class=wide onclick="startDue()" ${due.length?'':'disabled'}>🔁 ${L('Yanlışlarımı tekrarla','Review my mistakes')}</button><button onclick="quiz(()=>sh(COL).slice(0,10).map(collQuestion),0,'collocation')">🧩 ${L('Boşluk doldur','Fill the gap')}</button><button onclick="collMatch()">🔗 ${L('Eşleştir','Match')}</button><button onclick="collRepair()">🛠️ ${L('Hatayı düzelt','Correct the mistake')}</button><button onclick="collBuild()">✍️ ${L('Cümle kur','Build a sentence')}</button><button class=wide onclick="collList()">📚 ${L('Tüm birliktelikler','All word partnerships')}</button></div><div class=card><small>${L('İpucusuz doğru cevaplarda tekrar aralığı: 1, 3, 7, 14, 30 gün. Yanlış veya ipucu kullanımı aralığı sıfırlar.','Review intervals after unassisted correct answers: 1, 3, 7, 14, 30 days. A mistake or hint resets the interval.')}</small></div>`,'collocations')};
