function miniLesson(q){const w=q.w;let rule=w.reading?L('Doğru cevabı metindeki bilgiyle eşleştir; metinde bulunmayan bilgiyi varsayma.','Match the correct answer to evidence in the passage. Do not assume information the passage does not give.'):w.coll?L(`Doğal ifade: ${w.w}. Kelimeleri birlikte hatırla.`,`Natural expression: ${w.w}. Learn the words together.`):w.id?(bukiLang==='en'?EN_RULES[+w.id.split(':')[0]]:w.t):L(`${w.w}: ${w.t}. Örnek cümledeki kullanımına bak.`,`Use “${w.w}” in the context shown below.`);const candidates=w.reading?readingQuestions().filter(x=>x.w.w!==w.w):w.id&&!w.coll?gq(+w.id.split(':')[0]).filter(x=>x.w.id!==w.id):w.coll?COL.filter(c=>c.id!==w.id).sort((a,b)=>Number(b.w.split(' ')[0]===w.w.split(' ')[0])-Number(a.w.split(' ')[0]===w.w.split(' ')[0])).map(collQuestion):W.filter(x=>x.w!==w.w).map(qf);const next=candidates[0];window.bukiMiniNext=()=>next&&quiz(()=>[next],0,'mini');return `<div class="mini-lesson" data-no-translate><h3>💡 ${L('Kısa ders','Mini lesson')}</h3><p>${esc(rule)}</p>${w.coll||!w.id?`<p lang=en>${esc((w.s||'').replace(/[\[\]]/g,''))}</p>`:''}<button class=opt onclick="bukiMiniNext()">${L('Benzer bir soruda dene','Try a related question')}</button></div>`}
const EN_RULES=[
'Use Past Simple for a finished time: yesterday, ago, last week. Use have/has + past participle for experience or a present result. Use since for a starting point and for for a duration. Past Perfect (had + past participle) marks the earlier of two past events. Perfect Continuous focuses on duration.',
'Zero: if + present, present. First: if + present, will + verb. Second: if + past, would + verb. Third: if + had + past participle, would have + past participle. A mixed conditional connects a past condition to a present result. Unless means if not.',
'The passive uses be + past participle. Change be to match the tense: is done, was done, has been done, will be done. Use by for the agent. Intransitive verbs such as happen and arrive cannot be passive.',
'In reported speech, past reporting verbs often move the tense back: is → was; has done → had done; will → would. Tell needs a person; say does not. Indirect questions use statement word order without do or did.',
'Use who for people, which for things, whose for possession and where for places. Defining clauses identify the noun. Non-defining clauses add information with commas; do not use that or omit the relative pronoun in them.',
'Modals take the base verb without to (except ought to). Must expresses strong deduction; might/could/may express possibility; cannot expresses impossibility. For past deductions use modal + have + past participle. Must not is prohibition; do not have to means no necessity.',
'Enjoy, avoid, suggest, finish and consider take -ing. Want, decide, hope and plan take to + verb. Stop doing means end an activity; stop to do means pause another activity. Remember doing recalls the past; remember to do is a task.',
'Although/even though + subject + verb. Despite/in spite of + noun or -ing. Because + clause; because of + noun. So + adjective; such + noun phrase. Do not use although and but together.',
'Will is used for spontaneous decisions, predictions and promises. Be going to is for intentions and evidence-based predictions. Present Continuous describes arrangements. Use Present Simple after when, until and as soon as for future events.',
'Wish + past simple expresses an unreal present wish. Wish + past perfect expresses past regret. Wish + would expresses a desired change in another person or situation. If only makes the wish stronger.',
'Use -er/-est for short adjectives and more/most for longer ones. Do not combine more with -er. Use as + adjective + as for equality. The comparative + the comparative shows connected changes.',
'A/an is for one non-specific countable noun; choose by sound. The is for a specific or known noun. Much/little go with uncountable nouns; many/few with plurals. A few/a little mean some; few/little emphasize not enough.',
'Prefixes change meaning: un-, im-, dis-, re-, mis-. Suffixes change word class: -tion/-ment/-ness (noun), -ful/-less/-able (adjective), -ly (adverb), -en/-ify (verb). Check the grammar around the gap before choosing a form.'
];
const oldGt=gt;gt=function(i){if(bukiLang!=='en')return oldGt(i);plusRender(backBar('Grammar')+`<div class=card><h2>${esc(G[i].n)}</h2><p style="text-align:left">${esc(EN_RULES[i]||'Read the example and choose the form that fits the sentence.')}</p></div><div class=grid><button onclick="quiz(()=>gq(${i}))">Multiple choice</button><button onclick="quiz(()=>gtp(${i}))">Type the answer</button></div>`,'grammar')};
function dashboard(){const rows=BukiCore.stats(pState);plusRender(backBar(L('Eksiklerim','My progress'))+`<div class=card><h1>${L('Nereye odaklanmalıyım?','Where should I focus?')}</h1><p>${L('Her konuda son 50 cevap. İpucuyla verilen cevaplar bağımsız başarı sayılmaz. 5 cevaptan azsa sonuç başlangıç göstergesidir.','Last 50 answers per topic. Hinted answers do not count as independent success. Fewer than 5 answers is an early indication.')}</p></div>${rows.length?rows.map(r=>`<div class=card><div class=bar><b>${esc(topicName(r.topic))}</b><b>${r.percent}%</b></div><progress value="${r.percent}" max=100 aria-label="${esc(topicName(r.topic))}"></progress><small>${r.n} ${L('cevap','answers')}${r.n<5?' · '+L('erken veri','early data'):''}</small><button class=opt data-topic="${esc(r.topic)}">${L('Bu konuyu çalış','Practise this topic')}</button></div>`).join(''):`<div class=card>${L('Birkaç alıştırma çöz; eksiklerin burada görünecek.','Complete some practice to see your strengths and gaps here.')}</div>`}`,'dashboard');app.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>targetPractice(b.dataset.topic))}
function targetPractice(topic){if(topic.startsWith('grammar:'))return quiz(()=>gq(+topic.split(':')[1]),0,'target');if(topic==='collocation')return quiz(()=>sh(COL).slice(0,10).map(collQuestion),0,'collocation');if(topic==='reading')return rd();if(topic==='listening')return listening();return quiz(mc(0),0,'target')}
function todayProgress(){const a=pState.days[BukiCore.day(Date.now())]||[];return {review:a.filter(e=>e.kind==='answer'&&e.payload.mode==='review'&&e.payload.ok&&!e.payload.hint).length,coll:a.filter(e=>e.kind==='answer'&&e.payload.topic==='collocation').length,reading:a.some(e=>e.kind==='activity'&&e.payload.type==='reading')}}
function dailyPlan(){const p=todayProgress();plusRender(backBar(L('Bugünkü plan','Today’s plan'))+`<div class=card><h1>${L('Bugün 15 dakika','15 minutes today')}</h1><p>${L('Tekrar et, bağlamda öğren, kısa bir metin oku. Görevler gerçek çalışmalarından tamamlanır.','Review, learn in context, and read a short text. Tasks complete from your actual activity.')}</p></div><div class=card><h2>${p.review>=5||!pState.due.length?'✅':'🔁'} ${L('Yanlışlarını tekrarla','Review mistakes')}</h2><p>${pState.due.length?Math.min(5,p.review)+'/5':L('Zamanı gelen tekrar yok','No reviews due')}</p><button class=opt onclick="startDue()" ${pState.due.length?'':'disabled'}>${L('Başla','Start')}</button></div><div class=card><h2>${p.coll>=5?'✅':'🧩'} 5 collocations</h2><p>${Math.min(5,p.coll)}/5</p><button class=opt onclick="quiz(()=>sh(COL).slice(0,5).map(collQuestion),0,'collocation')">${L('Çalış','Practise')}</button></div><div class=card><h2>${p.reading?'✅':'📖'} ${L('Bir metin oku ve sorularını çöz','Read a text and answer its questions')}</h2><button class=opt onclick="rd()">${L('Metni aç','Open text')}</button></div>`,'daily')}
function collMatch(){const heads=new Set();const selected=sh(COL).filter(w=>{const h=w.w.split(' ')[0];if(heads.has(h))return false;heads.add(h);return true}).slice(0,5),parts=selected.map(w=>({w,left:w.w.split(' ')[0],right:w.w.split(' ').slice(1).join(' ')}));let pick=null,done=new Set();plusRender(backBar('Collocations')+`<div class=card><h1>${L('Birliktelikleri eşleştir','Match the partnerships')}</h1><div class=mt>${parts.map((p,i)=>`<button data-left=${i}>${esc(p.left)}</button>`).join('')}${sh(parts).map(p=>`<button data-right=${parts.indexOf(p)}>${esc(p.right)}</button>`).join('')}</div><p id=collFeedback role=status></p></div>`,'match');app.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{if(done.has(+b.dataset.left))return;pick=+b.dataset.left;app.querySelectorAll('[data-left]').forEach(x=>x.classList.toggle('sel',x===b))});app.querySelectorAll('[data-right]').forEach(b=>b.onclick=()=>{if(pick===null||b.disabled)return;const n=+b.dataset.right,ok=parts[pick].w.w===parts[pick].left+' '+parts[n].right;recordAnswer(collQuestion(parts[pick].w),ok,false);document.getElementById('collFeedback').textContent=ok?L('Doğru eşleşme!','Correct match!'):L('Bu ikili doğal değil. Tekrar dene.','That is not the natural partnership. Try again.');if(ok){done.add(pick);b.disabled=true;app.querySelector(`[data-left="${pick}"]`).disabled=true;pick=null;if(done.size===5)document.getElementById('collFeedback').textContent=L('Hepsi tamam!','All complete!')}})}
const REPAIRS=[['do progress','make progress',0],['do an effort','make an effort',1],['make responsibility','take responsibility',2],['catch a deadline','meet a deadline',3],['lift awareness','raise awareness',4],['make research','conduct research',6],['arrive a conclusion','reach a conclusion',7],['big rain','heavy rain',9],['depend of','rely on',12],['aware about','aware of',14],['take attention','pay attention',20],['do a decision','make a decision',21]];
