function collBuild(){const w=sh(COL)[0],tokens=w.s.replace(/[\[\].]/g,'').split(' ');let picked=[],used=new Set(),finished=false;const mixed=sh(tokens.map((text,id)=>({text,id})));plusRender(backBar('Collocations')+`<div class=card><h1>${L('Cümleyi sırala','Build the sentence')}</h1><p><b>${esc(w.w)}</b></p><p id=built aria-live=polite>…</p><div class=token-grid>${mixed.map(t=>`<button data-token=${t.id}>${esc(t.text)}</button>`).join('')}</div><div class=row><button id=undo>${L('Geri al','Undo')}</button><button id=buildCheck>${L('Kontrol et','Check')}</button></div><div id=buildResult role=status></div></div>`,'build');app.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{if(finished)return;picked.push(+b.dataset.token);used.add(+b.dataset.token);b.disabled=true;document.getElementById('built').textContent=picked.map(i=>tokens[i]).join(' ')});document.getElementById('undo').onclick=()=>{if(finished)return;const id=picked.pop();if(id!==undefined){used.delete(id);app.querySelector(`[data-token="${id}"]`).disabled=false;document.getElementById('built').textContent=picked.map(i=>tokens[i]).join(' ')||'…'}};document.getElementById('buildCheck').onclick=()=>{if(finished)return;if(picked.length!==tokens.length){document.getElementById('buildResult').textContent=L('Tüm kelimeleri kullan.','Use all the words.');return}finished=true;const ok=BukiCore.normalize(picked.map(i=>tokens[i]).join(' '))===BukiCore.normalize(tokens.join(' '));recordAnswer(collQuestion(w),ok,false);document.getElementById('buildResult').innerHTML=`<p>${ok?'✅':'↻'} ${esc(w.s.replace(/[\[\]]/g,''))}</p><small>${L('Bu alıştırma örnek cümlenin sırasını kontrol eder. Başka sıralamalar bazı cümlelerde geçerli olabilir.','This exercise checks the model word order. Other orders can be valid in some sentences.')}</small><button class=opt onclick="collBuild()">${L('Yeni cümle','New sentence')}</button>`}}
